const input = $input.first().json;
const required = ['tenantId','automationInstanceId','traceId','occurredAt'];
const missing = required.filter((k) => input[k] === undefined || input[k] === null || input[k] === '');
if (missing.length) {
  throw new Error(`ERROR_TO_INCIDENT_INVALID_INPUT missing=${missing.join(',')}`);
}
const redact = (value) => {
  if (value === undefined || value === null) return null;
  let s = String(value).slice(0, 4000);
  s = s.replace(/Bearer\s+[A-Za-z0-9._~+\/-]+=*/gi, 'Bearer [REDACTED]');
  s = s.replace(/(api[_-]?key|token|password|secret)\s*[:=]\s*[^\s,;]+/gi, '$1=[REDACTED]');
  return s;
};
const code = input.error?.code || input.code || 'AUTOMATION_FAILURE';
const source = input.source || input.nodeName || input.error?.source || 'unknown';
const incident = {
  schemaVersion: '1.0',
  tenantId: String(input.tenantId),
  automationInstanceId: String(input.automationInstanceId),
  traceId: String(input.traceId),
  runId: input.runId ? String(input.runId) : null,
  occurredAt: new Date(input.occurredAt).toISOString(),
  severity: String(input.severity || 'error'),
  status: 'open',
  source: redact(source),
  provider: redact(input.provider),
  nodeName: redact(input.nodeName),
  error: {
    code: redact(code),
    message: redact(input.error?.message || input.message || 'Automation failed'),
    retryable: Boolean(input.error?.retryable ?? input.retryable ?? false),
    category: redact(input.error?.category || input.category || 'runtime')
  },
  metadata: input.metadata && typeof input.metadata === 'object' ? input.metadata : {}
};
const fingerprintSource = `${incident.error.code}:${incident.source}:${incident.nodeName || ''}`;
incident.idempotencyKey = input.idempotencyKey
  ? String(input.idempotencyKey)
  : `incident:${incident.tenantId}:${incident.automationInstanceId}:${incident.traceId}:${fingerprintSource}`;
return [{ json: incident }];
